//! Conformance: Dry `simulate` must reproduce the FullControl oracle's metrics on every fixture under
//! `conformance/simulate/` (generated by `conformance/oracle/gen_simulate.py`). Clean-room: we match the
//! oracle's *outputs*, not its code (`docs/CLEANROOM.md`).

use dry_core::{simulate, Metrics, Toolpath};
use serde::Deserialize;
use std::fs;
use std::path::PathBuf;

#[derive(Deserialize)]
struct Fixture {
    design: String,
    ir: Toolpath,
    expected: Metrics,
}

fn corpus_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../conformance/simulate")
}

/// Relative+absolute float comparison (cross-language sums can differ by a few ULP).
fn close(a: f64, b: f64) -> bool {
    let d = (a - b).abs();
    d <= 1e-9 || d <= 1e-9 * a.abs().max(b.abs())
}

fn check(name: &str, got: &Metrics, want: &Metrics) {
    let fields: [(&str, f64, f64); 8] = [
        (
            "total_time_s",
            got.total_time_s.value(),
            want.total_time_s.value(),
        ),
        (
            "print_time_s",
            got.print_time_s.value(),
            want.print_time_s.value(),
        ),
        (
            "travel_time_s",
            got.travel_time_s.value(),
            want.travel_time_s.value(),
        ),
        (
            "extruding_distance",
            got.extruding_distance.value(),
            want.extruding_distance.value(),
        ),
        (
            "travel_distance",
            got.travel_distance.value(),
            want.travel_distance.value(),
        ),
        (
            "extruded_volume",
            got.extruded_volume.value(),
            want.extruded_volume.value(),
        ),
        (
            "filament_length",
            got.filament_length.value(),
            want.filament_length.value(),
        ),
        (
            "max_flow_rate",
            got.max_flow_rate.value(),
            want.max_flow_rate.value(),
        ),
    ];
    for (field, g, w) in fields {
        assert!(close(g, w), "[{name}] {field}: got {g}, oracle {w}");
    }
    assert_eq!(
        got.segment_count, want.segment_count,
        "[{name}] segment_count"
    );
}

#[test]
fn simulate_matches_the_fullcontrol_oracle() {
    let dir = corpus_dir();
    let mut checked = 0;
    for entry in fs::read_dir(&dir).expect("conformance/simulate exists") {
        let path = entry.unwrap().path();
        if path.extension().and_then(|e| e.to_str()) != Some("json") {
            continue;
        }
        let fx: Fixture = serde_json::from_str(&fs::read_to_string(&path).unwrap())
            .unwrap_or_else(|e| panic!("parse {path:?}: {e}"));
        let got = simulate(&fx.ir);
        check(&fx.design, &got, &fx.expected);
        checked += 1;
    }
    assert!(checked >= 1, "no fixtures found in {dir:?}");
    eprintln!("simulate conformance: {checked} fixtures matched the FullControl oracle");
}
